// ============================================================================
// PAYLOAD VALIDATION & NORMALIZATION
// ============================================================================
// This node validates the incoming webhook payload and ensures data quality
// before processing. It handles missing/malformed data gracefully.

const item = $input.item.json;

// Extract body (handles both direct body and nested structures)
const body = item.body || item;

// Required fields - at least email or phone must exist
const email = (body.email || '').trim().toLowerCase();
const phone = (body.phone || '').trim();

// If neither email nor phone exists, this is invalid
if (!email && !phone) {
  return {
    json: {
      valid: false,
      reason: 'Missing both email and phone',
      rawData: body
    }
  };
}

// Normalize and validate data
const normalized = {
  // Core lead data (with defaults for missing fields)
  name: (body.name || 'Unknown').trim(),
  email: email || 'N/A',
  phone: phone || 'N/A',
  message: (body.message || '').trim(),

  // Contextual data
  sourceUrl: body.sourceUrl || 'Unknown',
  pageTitle: body.pageTitle || 'Unknown',
  referrer: body.referrer || 'Direct',
  customerId: body.customerId || 'unknown',

  // Technical metadata
  userAgent: body.userAgent || 'Unknown',
  screenResolution: body.screenResolution || 'Unknown',
  formId: body.formId || 'unknown-form',

  // Spam detection helpers
  honeypotValue: body.honeypotValue || '',
  submissionMethod: body.submissionMethod || 'traditional',

  // Timestamps
  submittedAt: body.timestamp || new Date().toISOString(),
  processedAt: new Date().toISOString(),

  // Raw data for debugging
  rawFields: body.rawFields || {},

  // Validation flag
  valid: true
};

return { json: normalized };

// ============================================================================
// SPAM DETECTION ENGINE
// ============================================================================
// Multi-factor spam scoring system with explainable logic
// Score >= 50 = Possible Spam, Score < 50 = New Lead

const lead = $input.item.json;
let spamScore = 0;
const signals = [];

// ============================================================================
// SIGNAL 1: Disposable Email Domains (30 points)
// ============================================================================
const disposableDomains = [
  'tempmail.com', 'guerrillamail.com', '10minutemail.com', 'throwaway.email',
  'mailinator.com', 'maildrop.cc', 'trashmail.com', 'yopmail.com',
  'temp-mail.org', 'fakeinbox.com', 'sharklasers.com', 'getnada.com'
];

const emailDomain = lead.email.split('@')[1];
if (disposableDomains.includes(emailDomain)) {
  spamScore += 30;
  signals.push('Disposable email domain detected');
}

// ============================================================================
// SIGNAL 2: Honeypot Field Filled (40 points)
// ============================================================================
// If honeypot field has a value, it's almost certainly a bot
if (lead.honeypotValue && lead.honeypotValue.trim().length > 0) {
  spamScore += 40;
  signals.push('Honeypot field was filled (likely bot)');
}

// ============================================================================
// SIGNAL 3: Missing Critical Fields (20 points)
// ============================================================================
// Spam often has email but missing name AND message
const hasName = lead.name && lead.name !== 'Unknown' && lead.name.length > 1;
const hasMessage = lead.message && lead.message.length > 5;

if (!hasName && !hasMessage) {
  spamScore += 20;
  signals.push('Missing both name and message');
}

// ============================================================================
// SIGNAL 4: Suspicious Email Patterns (25 points)
// ============================================================================
// Common spam patterns: random characters, numbers only, etc.
const emailLocalPart = lead.email.split('@')[0];

// Check for excessive numbers (e.g., user123456789@example.com)
const numberRatio = (emailLocalPart.match(/\d/g) || []).length / emailLocalPart.length;
if (numberRatio > 0.6) {
  spamScore += 15;
  signals.push('Email contains excessive numbers');
}

// Check for very short email (e.g., a@b.com)
if (emailLocalPart.length < 3) {
  spamScore += 10;
  signals.push('Suspiciously short email address');
}

// ============================================================================
// SIGNAL 5: Spam Keywords in Message (15 points)
// ============================================================================
const spamKeywords = [
  'buy now', 'click here', 'free money', 'earn cash', 'lose weight',
  'viagra', 'casino', 'lottery', 'nigerian prince', 'act now',
  'limited time', 'special promotion', 'congratulations', 'you won'
];

const messageLower = lead.message.toLowerCase();
const matchedKeywords = spamKeywords.filter(keyword => messageLower.includes(keyword));

if (matchedKeywords.length > 0) {
  spamScore += 15;
  signals.push(`Spam keywords detected: ${matchedKeywords.join(', ')}`);
}

// ============================================================================
// SIGNAL 6: Suspicious Name Patterns (10 points)
// ============================================================================
// Check for single character names, all numbers, etc.
if (hasName) {
  if (lead.name.length === 1) {
    spamScore += 5;
    signals.push('Single character name');
  }

  if (/^\d+$/.test(lead.name)) {
    spamScore += 5;
    signals.push('Name is all numbers');
  }
}

// ============================================================================
// CLASSIFICATION
// ============================================================================
const threshold = 50;
const classification = spamScore >= threshold ? 'Possible Spam' : 'New Lead';

// Return enriched lead with spam analysis
return {
  json: {
    ...lead,
    spamScore: spamScore,
    spamSignals: signals,
    status: classification,
    confidence: spamScore >= 70 ? 'High' : spamScore >= 50 ? 'Medium' : 'Low'
  }
};

