// Log spam detection for monitoring
const lead = $input.item.json;

console.log('========================================');
console.log('POSSIBLE SPAM DETECTED');
console.log('========================================');
console.log('Email:', lead.email);
console.log('Spam Score:', lead.spamScore);
console.log('Signals:', lead.spamSignals.join(', '));
console.log('Customer:', lead.customerId);
console.log('========================================');

return { json: lead };

// Store customer configuration
// In production, this would be stored in a database or environment variables
// For now, we'll use a simple mapping

const customerConfig = {
  'acme-corp': {
    email: 'sales@acme-corp.com',
    name: 'ACME Corporation'
  },
  'beta-inc': {
    email: 'leads@beta-inc.com',
    name: 'Beta Inc'
  },
  'gamma-llc': {
    email: 'contact@gamma-llc.com',
    name: 'Gamma LLC'
  }
};

const lead = $input.item.json;
const config = customerConfig[lead.customerId] || {
  email: process.env.DEFAULT_NOTIFICATION_EMAIL || 'admin@yourcompany.com',
  name: lead.customerId
};

return {
  json: {
    ...lead,
    customerEmail: config.email,
    customerName: config.name
  }
};
